```sql
SELECT degrees(ST_Azimuth(
    (SELECT geometry FROM pois WHERE poi_name ILIKE '%Red Wolf Sanctuary%' AND addr_city ILIKE '%Rising Sun%' AND addr_state ILIKE '%IN%' LIMIT 1),
    (SELECT geometry FROM pois WHERE tourism = 'gallery' AND ST_DWithin(
        (SELECT geometry FROM pois WHERE poi_name ILIKE '%Red Wolf Sanctuary%' AND addr_city ILIKE '%Rising Sun%' AND addr_state ILIKE '%IN%' LIMIT 1)::geography,
        geometry::geography, 50000
    ) LIMIT 1)
)) AS direction_degrees;
```

