SELECT degrees(ST_Azimuth(
    (SELECT geometry FROM regions WHERE region_name ILIKE '%Point Lookout%' LIMIT 1)::geography,
    (SELECT geometry FROM pois WHERE tourism = 'attraction' AND ST_DWithin(
        (SELECT geometry FROM regions WHERE region_name ILIKE '%Point Lookout%' LIMIT 1)::geography,
        pois.geometry::geography, 70000
    ) LIMIT 1)::geography
)) AS direction_degrees;
