SELECT degrees(ST_Azimuth(
    (SELECT geometry FROM pois WHERE poi_name ILIKE '%Historic Trade: Cook%' AND addr_city ILIKE '%Williamsburg%' AND addr_state ILIKE '%VA%' LIMIT 1)::geography,
    (SELECT ST_Centroid(geometry) FROM parks WHERE park_name ILIKE '%garden%' AND ST_DWithin(
        parks.geometry::geography,
        (SELECT geometry FROM regions WHERE region_name ILIKE '%Williamsburg%' AND border_type = 'city' LIMIT 1)::geography,
        100000
    ) LIMIT 1)::geography
)) AS heading_degrees;
```

